        if(i==2){String url=ChannelUrls.parse(v.channelId);if(url==null){toast("Open the video to load channel details first.");return;}channel=url;query="";show("Search");}
        if(i==3){Set<String> blocked=new HashSet<>(app.prefs.data.getStringSet("blocked",Collections.emptySet()));blocked.add(v.channelId);app.prefs.data.edit().putStringSet("blocked",blocked).apply();videos.removeIf(x->x.channelId.equals(v.channelId));adapter.notifyDataSetChanged();}
