        option(p,"Panel padding","panel_padding","20",new String[]{"8","12","16","20","24","28","32"},true);
        toggle(p,"Show channel on cards","Include channel names in results.","card_channel",true,false);toggle(p,"Show duration on cards","Include video duration.","card_duration",true,false);
        section(p,"Playback engine");option(p,"Download connections","download_connections","2",new String[]{"1","2","3"},false);option(p,"Buffer budget (seconds)","buffer_seconds","60",new String[]{"15","30","60","90","120"},false);toggle(p,"Chunked media transfers","Use bounded CDN requests for progressive playback.","chunked_streaming",true,false);toggle(p,"Defer automatic imports during playback","Give audio and video priority over new scheduled imports.","defer_imports_playback",true,false);
        option(p,"Video surface","surface","SurfaceView",new String[]{"SurfaceView","TextureView"},false);
        option(p,"Preferred codecs","codec","AVC first",new String[]{"AVC first","Balanced","VP9 first"},false);
        toggle(p,"Decoder fallback","Try another available decoder after a codec error.","decoder_fallback",true,false);
        toggle(p,"Automatic format fallback","Try another extracted stream after a playback failure.","format_fallback",true,false);
        toggle(p,"Play video when opened","Start native playback after loading.","autoplay_video",true,false);
        toggle(p,"Keep screen awake","Keep the screen on while native playback is active.","keep_awake",true,false);
        toggle(p,"Loop current video","Replay after it finishes.","loop_video",false,false);
        option(p,"Seek buttons (seconds)","seek_seconds","10",new String[]{"5","10","15","30","60"},false);
        option(p,"Video fit","video_fit","Fit",new String[]{"Fit","Fill","Zoom"},false);
        option(p,"Caption language","caption_language","en",new String[]{"en","es","fr","de","it","pt","ja","ko","system"},false);
        option(p,"Caption text size","caption_size","18",new String[]{"14","16","18","20","24","28"},false);
        option(p,"Starting speed","speed","1.0",new String[]{"0.5","0.75","1.0","1.25","1.5","1.75","2.0","2.5","3.0"},false);
        section(p,"Comments and ratings");
        toggle(p,"Load comments automatically","Public comments load independently of login and playback.","comments_auto",true,false);
        option(p,"Maximum loaded comments","comments_limit","100",new String[]{"40","60","100","200","400"},false);
        toggle(p,"Show aggregate ratings","Retrieve rating evidence separately from account actions.","ratings_enabled",true,false);
        toggle(p,"Return YouTube Dislike","Use RYD estimates; video IDs are sent to the provider.","ratings_ryd",true,false);
        setting(p,"Optional Invidious ratings source",app.prefs.text("ratings_instance","").isEmpty()?"Not configured":app.prefs.text("ratings_instance",""),()->input("HTTPS instance URL","https://your-instance.example",value->{String base=RatingsRepository.instance(value);if(base==null)throw new IllegalArgumentException("Enter a public HTTPS instance URL");app.prefs.put("ratings_instance",base);app.votes.clear();show(screen);}));
        setting(p,"Remove optional ratings source","Keep YouTube and RYD",()->{app.prefs.put("ratings_instance","");app.votes.clear();show(screen);});
        setting(p,"Rating source information","YouTube-reported likes and labeled provider estimates",()->new AlertDialog.Builder(this).setTitle("Ratings sources").setMessage("Return YouTube Dislike: https://returnyoutubedislike.com\nInvidious API: https://docs.invidious.io/api/\n\nDislike counts are estimates. Providers can share the same dataset, so counts are never summed into a fabricated total.").setPositiveButton("Close",null).show());
        section(p,"Content and account behavior");
        setting(p,"Home discovery query",app.prefs.text("home_query","new videos"),()->input("Home topic","Search topic",v->{if(v.isEmpty())throw new IllegalArgumentException("Enter a topic");app.prefs.put("home_query",v);show(screen);}));
        option(p,"Content language","language","en",new String[]{"en","es","fr","de","it","pt","ja","ko"},false);
        option(p,"Content region","region","US",new String[]{"US","GB","CA","AU","DE","FR","JP","BR"},false);
        option(p,"Subscribe button target","subscription_target","Local",new String[]{"Local","YouTube","Both"},false);
        option(p,"Account index for older sessions","auth_user","0",new String[]{"0","1","2","3"},false);
        toggle(p,"Download on unmetered connections","Reject new download work on a metered connection.","download_unmetered",false,false);
        setting(p,"Test player without network","Generated color bars and tone isolate renderer/decoder problems",()->startActivity(new Intent(this,PlayerActivity.class).putExtra("renderer_test",true)));
        setting(p,"Playback diagnostics","View recent states and error codes; no session cookies or stream URLs",()->new AlertDialog.Builder(this).setTitle("Diagnostics").setMessage(Diagnostics.report()).setPositiveButton("Close",null).show());
